CREATE TABLE IF NOT EXISTS invoice_extraction_documents (
  id INTEGER PRIMARY KEY,
  document_id INTEGER NOT NULL UNIQUE REFERENCES documents(id),
  company_id INTEGER NOT NULL REFERENCES companies(id),
  sha256_hash TEXT NOT NULL UNIQUE,
  pdf_bytes BLOB NOT NULL,
  byte_length INTEGER NOT NULL CHECK(byte_length > 0 AND byte_length <= 10485760),
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS invoice_extraction_attempts (
  id INTEGER PRIMARY KEY,
  extraction_document_id INTEGER NOT NULL REFERENCES invoice_extraction_documents(id),
  extractor_id TEXT NOT NULL,
  extractor_version TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('started','completed','failed','needs_resolution')),
  failure_text TEXT,
  created_at TEXT NOT NULL,
  UNIQUE(extraction_document_id, extractor_id, extractor_version)
);
CREATE TABLE IF NOT EXISTS invoice_extraction_results (
  id INTEGER PRIMARY KEY,
  attempt_id INTEGER NOT NULL UNIQUE REFERENCES invoice_extraction_attempts(id),
  result_json TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS invoice_extraction_fields (
  id INTEGER PRIMARY KEY,
  result_id INTEGER NOT NULL REFERENCES invoice_extraction_results(id),
  field_key TEXT NOT NULL,
  value_json TEXT NOT NULL,
  confidence REAL NOT NULL CHECK(confidence >= 0 AND confidence <= 1),
  page_number INTEGER NOT NULL CHECK(page_number > 0),
  source_text TEXT NOT NULL,
  box_json TEXT,
  UNIQUE(result_id, field_key)
);
CREATE TABLE IF NOT EXISTS invoice_extraction_resolutions (
  id INTEGER PRIMARY KEY,
  attempt_id INTEGER NOT NULL REFERENCES invoice_extraction_attempts(id),
  field_key TEXT NOT NULL,
  resolution_json TEXT NOT NULL,
  resolved_by TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS company_supplier_recognitions (
  id INTEGER PRIMARY KEY,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  identifier_kind TEXT NOT NULL CHECK(identifier_kind IN ('dk_cvr','eu_vat','non_eu')),
  identifier TEXT NOT NULL,
  supplier_name TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(company_id, identifier_kind, identifier)
);
CREATE TRIGGER invoice_extraction_documents_no_update BEFORE UPDATE ON invoice_extraction_documents BEGIN SELECT RAISE(ABORT, 'invoice extraction documents are immutable'); END;
CREATE TRIGGER invoice_extraction_documents_no_delete BEFORE DELETE ON invoice_extraction_documents BEGIN SELECT RAISE(ABORT, 'invoice extraction documents are immutable'); END;
CREATE TRIGGER invoice_extraction_attempts_no_update BEFORE UPDATE ON invoice_extraction_attempts BEGIN SELECT RAISE(ABORT, 'invoice extraction attempts are immutable'); END;
CREATE TRIGGER invoice_extraction_attempts_no_delete BEFORE DELETE ON invoice_extraction_attempts BEGIN SELECT RAISE(ABORT, 'invoice extraction attempts are immutable'); END;
CREATE TRIGGER invoice_extraction_results_no_update BEFORE UPDATE ON invoice_extraction_results BEGIN SELECT RAISE(ABORT, 'invoice extraction results are immutable'); END;
CREATE TRIGGER invoice_extraction_results_no_delete BEFORE DELETE ON invoice_extraction_results BEGIN SELECT RAISE(ABORT, 'invoice extraction results are immutable'); END;
CREATE TRIGGER invoice_extraction_fields_no_update BEFORE UPDATE ON invoice_extraction_fields BEGIN SELECT RAISE(ABORT, 'invoice extraction fields are immutable'); END;
CREATE TRIGGER invoice_extraction_fields_no_delete BEFORE DELETE ON invoice_extraction_fields BEGIN SELECT RAISE(ABORT, 'invoice extraction fields are immutable'); END;
CREATE TRIGGER invoice_extraction_resolutions_no_update BEFORE UPDATE ON invoice_extraction_resolutions BEGIN SELECT RAISE(ABORT, 'invoice extraction resolutions are immutable'); END;
CREATE TRIGGER invoice_extraction_resolutions_no_delete BEFORE DELETE ON invoice_extraction_resolutions BEGIN SELECT RAISE(ABORT, 'invoice extraction resolutions are immutable'); END;
